# Debounce Function in JavaScript

Here's a comprehensive implementation with explanations:

## Basic Implementation

```javascript
function debounce(func, delay) {
  let timeoutId;

  return function(...args) {
    // Clear the previous timeout
    clearTimeout(timeoutId);

    // Set a new timeout
    timeoutId = setTimeout(() => {
      func.apply(this, args);
    }, delay);
  };
}
```

## Usage Example

```javascript
// Example: Search input handler
const handleSearch = (query) => {
  console.log('Searching for:', query);
  // API call would go here
};

const debouncedSearch = debounce(handleSearch, 500);

// Simulate user typing
debouncedSearch('j');      // Cancelled
debouncedSearch('ja');     // Cancelled
debouncedSearch('java');   // Cancelled
debouncedSearch('javascript'); // ✓ Executes after 500ms
```

## Advanced Implementation with Cancel & Flush

```javascript
function debounce(func, delay, options = {}) {
  let timeoutId;
  let lastArgs;
  let lastThis;
  let result;
  let lastCallTime;
  let lastInvokeTime = 0;
  let leading = options.leading || false;
  let trailing = options.trailing !== false; // true by default
  let maxWait = options.maxWait;

  function invokeFunc(time) {
    const args = lastArgs;
    const thisArg = lastThis;

    lastArgs = lastThis = undefined;
    lastInvokeTime = time;
    result = func.apply(thisArg, args);
    return result;
  }

  function shouldInvoke(time) {
    const timeSinceLastCall = time - (lastCallTime || 0);
    const timeSinceLastInvoke = time - lastInvokeTime;

    return (
      lastCallTime === undefined ||
      timeSinceLastCall >= delay ||
      timeSinceLastCall < 0 ||
      (maxWait && timeSinceLastInvoke >= maxWait)
    );
  }

  function timerExpired() {
    const time = Date.now();
    if (shouldInvoke(time)) {
      return trailingEdge(time);
    }
    const timeSinceLastCall = Date.now() - lastCallTime;
    const timeWaiting = delay - timeSinceLastCall;
    timeoutId = setTimeout(timerExpired, timeWaiting);
  }

  function trailingEdge(time) {
    timeoutId = undefined;
    if (trailing && lastArgs) {
      return invokeFunc(time);
    }
    lastArgs = lastThis = undefined;
    return result;
  }

  function cancel() {
    if (timeoutId !== undefined) {
      clearTimeout(timeoutId);
    }
    lastInvokeTime = 0;
    lastArgs = lastCallTime = lastThis = timeoutId = undefined;
  }

  function flush() {
    return timeoutId === undefined ? result : trailingEdge(Date.now());
  }

  function debounced(...args) {
    const time = Date.now();
    const isInvoking = shouldInvoke(time);

    lastArgs = args;
    lastThis = this;
    lastCallTime = time;

    if (isInvoking) {
      if (timeoutId === undefined && leading) {
        result = invokeFunc(time);
      }
      if (timeoutId === undefined) {
        timeoutId = setTimeout(timerExpired, delay);
      }
    }
    return result;
  }

  debounced.cancel = cancel;
  debounced.flush = flush;

  return debounced;
}
```

## Practical Examples

### Search Input
```javascript
const searchAPI = (query) => {
  console.log('API call with:', query);
};

const debouncedSearch = debounce(searchAPI, 300);

document.getElementById('search').addEventListener('input', (e) => {
  debouncedSearch(e.target.value);
});
```

### Window Resize
```javascript
const handleResize = () => {
  console.log('Window resized to:', window.innerWidth, window.innerHeight);
};

const debouncedResize = debounce(handleResize, 250);
window.addEventListener('resize', debouncedResize);
```

### Form Validation
```javascript
const validateEmail = (email) => {
  console.log('Validating:', email);
  // Validation logic
};

const debouncedValidate = debounce(validateEmail, 500);

document.getElementById('email').addEventListener('input', (e) => {
  debouncedValidate(e.target.value);
});
```

### With Cancel & Flush
```javascript
const debouncedFunc = debounce(() => {
  console.log('Executed!');
}, 1000);

debouncedFunc();
debouncedFunc();

// Cancel pending execution
debouncedFunc.cancel();

// Or force immediate execution
debouncedFunc.flush();
```

## Key Features

| Feature | Description |
|---------|-------------|
| **Basic** | Simple debounce with delay |
| **Cancel** | Stop pending execution |
| **Flush** | Execute immediately |
| **Leading** | Execute on leading edge |
| **Trailing** | Execute on trailing edge (default) |
| **MaxWait** | Maximum time before forced execution |

Choose the basic version for simple use cases, or the advanced version for more control!
